41:				dm.sendSystemMessage(net.minecraft.network.chat.Component
42:					.translatable("chat.dndsheets.dm_required").withStyle(net.minecraft.ChatFormatting.RED));
43:				return;
44:			}
45:			action.accept(dm);
46:		});
47:	}
